code_examples.background_grouping:
// Get tabs by group
const getTabsByGroup = async (windowId) => {
  const tabs = await chrome.tabs.query({windowId});
  const groups = {};

  tabs.forEach(tab => {
    const groupKey = tab.groupId === -1 ? 'ungrouped' : `group_${tab.groupId}`;
    if (!groups[groupKey]) {
      groups[groupKey] = [];
    }
    groups[groupKey].push(tab);
  });

  return groups;
};

