// Display groups in popup
const groups = await chrome.tabGroups.query({windowId});
for (const group of groups) {
  const groupEl = document.createElement('div');
  groupEl.innerHTML = `
    <span style="color: ${group.color}">${group.title || 'Untitled Group'}</span>
    <input type="number" id="group_${group.id}" value="${limit}" min="1" max="50">
    <button onclick="saveGroupLimit(${group.id})">Save</button>
  `;
}
